import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Processing attempts allowed per job, counting the first. */
export const MAX_ATTEMPTS = 3;
/** Duration of one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried (must be within 250 ms to 2 s). */
export const RETRY_DELAY_MS = 1000;
export const TRANSIENT_ERROR = 'transient failure';
/** A worker heartbeat older than this means the worker is down. */
export const WORKER_STALE_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function one(db: DatabaseSync, sql: string, params: (string | number | null)[] = []): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

function many(db: DatabaseSync, sql: string): JobRow[] {
  return db.prepare(sql).all() as unknown as JobRow[];
}

function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE id = ?', [id]);
}

export function findJobRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', [key]);
}

/** All jobs, newest first. */
export function listJobRows(db: DatabaseSync): JobRow[] {
  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

export function insertJob(db: DatabaseSync, sub: Submission, idempotencyKey: string | null): JobRow {
  const id = randomUUID();
  const now = new Date().toISOString();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                       idempotency_key, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(id, sub.input, sub.steps, sub.failAttempts, idempotencyKey, now, now);
  const row = getJobRow(db, id);
  if (!row) throw new Error(`inserted job ${id} not found`);
  return row;
}

/**
 * Claims the oldest queued job that is due, marking it running and counting the attempt.
 * Returns undefined when no job is due.
 */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return transaction(db, () => {
    const next = one(db, "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1", [nowMs]);
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
    ).run(new Date().toISOString(), next.seq);
    return one(db, 'SELECT * FROM jobs WHERE seq = ?', [next.seq]);
  });
}

/**
 * Called when a worker starts. Any job still `running` belonged to a worker that died mid-attempt.
 * If that attempt was the last allowed one, the job fails; otherwise it goes back to the queue.
 */
export function recoverInterruptedJobs(db: DatabaseSync): void {
  transaction(db, () => {
    const now = new Date().toISOString();
    db.prepare(
      "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE status = 'running' AND attempts >= ?",
    ).run(TRANSIENT_ERROR, now, MAX_ATTEMPTS);
    db.prepare(
      "UPDATE jobs SET status = 'queued', run_after = 0, progress_completed = 0, updated_at = ? WHERE status = 'running'",
    ).run(now);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

export function markCompleted(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE id = ?",
  ).run(output, new Date().toISOString(), id);
}

export function markFailed(db: DatabaseSync, id: string, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?").run(
    error,
    new Date().toISOString(),
    id,
  );
}

export function requeue(db: DatabaseSync, id: string, runAfterMs: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', run_after = ?, progress_completed = 0, updated_at = ? WHERE id = ?").run(
    runAfterMs,
    new Date().toISOString(),
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.exec('DELETE FROM worker_heartbeat');
}

export function isWorkerUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return row !== undefined && nowMs - Number(row.beat_at) <= WORKER_STALE_MS;
}

